            FormLinkBinaryTranslation.Instance.WriteNullable(
                writer: writer,
                item: item.Worldspace,
                header: translationParams.ConvertToCustom(RecordTypes.WNAM));
            Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<ReadOnlyMemorySlice<Byte>>.Instance.WritePerItem(
                writer: writer,
                items: item.RegionAreas,
                recordType: translationParams.ConvertToCustom(RecordTypes.RPLI),
                transl: ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Write);
            ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Write(
                writer: writer,
                item: item.RegionAreaData,
                header: translationParams.ConvertToCustom(RecordTypes.RPLD));
            Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<IRegionDataEntryGetter>.Instance.Write(
                writer: writer,
                items: item.RegionDataEntries,
                transl: (MutagenWriter subWriter, IRegionDataEntryGetter subItem, TypedWriteParams conv) =>
