    internal partial class RegionBinaryCreateTranslation : Fallout3MajorRecordBinaryCreateTranslation
    {
        public new static readonly RegionBinaryCreateTranslation Instance = new RegionBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.REGN;
        public static ParseResult FillBinaryRecordTypes(
            IRegionInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.ICON:
                {
                    item.Icons = Mutagen.Bethesda.Fallout3.Icons.CreateFromBinary(
                        frame: frame,
                        translationParams: translationParams.DoNotShortCircuit());
                    return (int)Region_FieldIndex.Icons;
                }
                case RecordTypeInts.RCLR:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MapColor = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Region_FieldIndex.MapColor;
                }
                case RecordTypeInts.WNAM:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.Worldspace.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Region_FieldIndex.Worldspace;
                }
                case RecordTypeInts.RPLI:
                {
                    item.RegionAreas.SetTo(
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<MemorySlice<Byte>>.Instance.Parse(
                            reader: frame,
                            triggeringRecord: translationParams.ConvertToCustom(RecordTypes.RPLI),
                            transl: ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse));
                    return (int)Region_FieldIndex.RegionAreas;
                }
                case RecordTypeInts.RPLD:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.RegionAreaData = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Region_FieldIndex.RegionAreaData;
                }
                case RecordTypeInts.RDAT:
                case RecordTypeInts.RDOT:
                case RecordTypeInts.RDMP:
                case RecordTypeInts.RDGS:
                case RecordTypeInts.RDMD:
                case RecordTypeInts.RDMO:
                case RecordTypeInts.RDSD:
                case RecordTypeInts.RDWT:
                {
                    item.RegionDataEntries.SetTo(
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<RegionDataEntry>.Instance.Parse(
                            reader: frame,
                            triggeringRecord: RegionDataEntry_Registration.TriggerSpecs,
                            translationParams: translationParams,
                            transl: RegionDataEntry.TryCreateFromBinary));
                    return (int)Region_FieldIndex.RegionDataEntries;
                }
                default:
                    return Fallout3MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
        }

    }

